package dev.kubejseditor.verification;

import com.google.gson.*;
import dev.kubejseditor.client.*;
import dev.kubejseditor.model.EditorProject.*;
import dev.kubejseditor.recipe.*;
import dev.kubejseditor.recipe.compat.*;
import dev.kubejseditor.runtime.*;
import dev.kubejseditor.storage.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import java.nio.file.*;
import java.util.*;

/** Real serializers, JEI coordinates and two actual launches. Never part of the production Jar. */
@EventBusSubscriber(modid="kubejs_editor_verification",value=Dist.CLIENT)
public final class ClientUniversalVerification {
    private static java.util.concurrent.CompletableFuture<JsonObject> nativeChecks;
    private static int phase,ticks,checks,stage,shotIndex;private static EditorRuntime.ReloadResult result;private static final JsonObject report=new JsonObject();private static final List<String> shots=new ArrayList<>();
    private static Path root(){return Minecraft.getInstance().gameDirectory.toPath();}
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static EditorRuntime.Loaded loaded(String id){return EditorRuntime.recipes().stream().filter(r->r.id().equals(id)).findFirst().orElseThrow(()->new AssertionError("Missing recipe "+id));}
    private static JsonObject nativeData(String id){return dev.kubejseditor.export.GenericFormatter.encodeRecipe(Minecraft.getInstance().getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse(id)).orElseThrow()).getAsJsonObject();}
    private static CompatibilityAdapter adapter(String id){return (CompatibilityAdapter)RecipeAdapters.get(loaded(id).type());}
    private static void saveReport()throws Exception{report.addProperty("checks",checks);report.addProperty("stage",stage);report.addProperty("phase",phase);Files.writeString(root().resolve("universal-stage"+stage+".json"),ProjectStore.JSON.toJson(report));}
    private static void finish()throws Exception{report.addProperty("passed",true);report.addProperty("checks",checks);for(String id:List.of("neoforge","jei","modern_industrialization","forbidden_arcanus","forbidden_arcanus_js","ars_nouveau"))report.addProperty(id,net.neoforged.fml.ModList.get().getModContainerById(id).orElseThrow().getModInfo().getVersion().toString());saveReport();phase=99;Minecraft.getInstance().stop();}
    private static RecipeDraft draft(String id){var r=loaded(id);check(r.error()==null,id+" imported: "+r.error());var d=new RecipeDraft(id,r.data());d.operation="replace";d.origin="existing";d.source=r.data().deepCopy();return d;}
    private static void queue(RecipeDraft d)throws Exception{CompatibilityRecipes.annotate(d);check(d.compatibility!=null,"Persistent compatibility metadata "+d.id);EditorRuntime.validateRecipe(d.data,Set.of());checks++;EditorRuntime.project().recipes.put(d.id,d);}
    private static void show(String id,int scale){var mc=Minecraft.getInstance();mc.options.guiScale().set(scale);mc.resizeDisplay();var value=EditorRuntime.project().recipes.get(id);if(value==null)value=EditorRuntime.state().applied.recipes.get(id);if(value==null){value=new RecipeDraft(id,loaded(id).data());value.operation="replace";}var screen=new CompatibilityScreen(new WorkspaceScreen(),value);mc.setScreen(screen);}
    private static void layouts(){var data=new JsonArray();report.add("layouts",data);for(String id:List.of("compat:mi_eight_four","compat:ritual","compat:apparatus_1","compat:apparatus_2","compat:apparatus_4","compat:apparatus_6","compat:apparatus_8")){var d=loaded(id).data();var a=adapter(id);var view=CompatJeiLayouts.create(id,d);check(view.layout()!=null,id+" JEI rebuild: "+view.error());var regions=CompatJeiLayouts.bind(id,view,a.presentation(d));int expected=id.contains("mi_")?13:id.contains("ritual")?12:Integer.parseInt(id.substring(id.lastIndexOf('_')+1))+2;var debug=new JsonObject();debug.addProperty("id",id);debug.add("slots",ProjectStore.JSON.toJsonTree(view.slots()));debug.add("native",d);debug.add("bindings",ProjectStore.JSON.toJsonTree(a.presentation(d).bindings()));data.add(debug);check(regions.size()==expected,id+" exact visual binding count "+regions.size()+" vs "+expected);var row=new JsonObject();row.addProperty("id",id);row.addProperty("rectangles",regions.size());row.add("regions",ProjectStore.JSON.toJsonTree(regions));data.add(row);}
        report.add("layouts",data);
    }
    private static void manualMapping()throws Exception{String id="compat:apparatus_1";var original=loaded(id).data();var p=adapter(id).presentation(original);var view=CompatJeiLayouts.create(id,original);var resource=p.bindings().stream().filter(b->b.path().equals("/sourceCost")).findFirst().orElseThrow();CompatJeiLayouts.mark(id,view,original,resource.key(),new net.minecraft.client.renderer.Rect2i(2,2,12,12));check(CompatJeiLayouts.readProfile(id,view,original)!=null,"Manual custom region persisted");check(CompatJeiLayouts.bind(id,view,p).containsKey(resource.key()),"Manual numeric region is editable alongside standard slots");var more=original.deepCopy();more.getAsJsonArray("pedestalItems").add(RecipeAdapters.parse("{item:'minecraft:iron_ingot'}"));var changed=CompatJeiLayouts.create(id,more);check(CompatJeiLayouts.readProfile(id,changed,more)==null,"Dynamic layout requires reconfirming manual marks");}
    private static void prepare()throws Exception{
        if(net.neoforged.fml.ModList.get().isLoaded("enderio")){var e=loaded("compat:enderio_generic");var a=adapter(e.id());check(a.definition.source.equals("kubejs-schema"),"Ender IO uses shared public schema without a dedicated profile");check(a.presentation(e.data()).bindings().stream().filter(b->b.field().slot()).count()==4,"Generic schema reads three alloy inputs and output");EditorRuntime.validateRecipe(e.data(),Set.of());checks++;CompatibilityRecipes.confirm(WorkspaceState.copy(a.definition,CompatDefinition.class),e.data());check(((CompatibilityAdapter)RecipeAdapters.get(e.type())).definition.source.equals("confirmed"),"Fourth mod accepts persisted user mapping");}

        var mi=draft("compat:mi_eight_four");var p=adapter(mi.id).presentation(mi.data);CompatJson.set(mi.data,"/eu",new JsonPrimitive(32));CompatJson.set(mi.data,"/duration",new JsonPrimitive(40));var item=p.bindings().getFirst();var value=p.item(item);value.addProperty("count",9);value.addProperty("chance",0);p.writeItem(item,value);var fluid=p.bindings().stream().filter(RecipePresentation.Binding::fluid).findFirst().orElseThrow();var f=p.item(fluid);f.addProperty("amount",250);p.writeItem(fluid,f);queue(mi);
        var ritual=draft("compat:ritual");var r=adapter(ritual.id).presentation(ritual.data);CompatJson.set(ritual.data,"/essences/aureal",new JsonPrimitive(50));CompatJson.set(ritual.data,"/forge_tier",new JsonPrimitive(2));CompatJson.set(ritual.data,"/enhancers",new JsonPrimitive("forbidden_arcanus:divine_pact"));CompatJson.set(ritual.data,"/match_tier_exact",new JsonPrimitive(true));var outer=r.bindings().getFirst();var material=r.item(outer);material.addProperty("item","minecraft:gold_ingot");r.writeItem(outer,material);check(r.bindings().stream().filter(b->!b.field().expand.isBlank()).count()==4,"Single pedestal edit preserves total");for(String mode:List.of("create_item","transmute_input","upgrade_tier")){var variant=ritual.data.deepCopy();CompatDefinitions.switchRitualResult(variant,"forbidden_arcanus:"+mode);EditorRuntime.validateRecipe(variant,Set.of());checks++;}queue(ritual);
        var ars=draft("compat:apparatus_6");CompatJson.set(ars.data,"/sourceCost",new JsonPrimitive(123));CompatJson.set(ars.data,"/keepNbtOfReagent",new JsonPrimitive(true));queue(ars);
        // Explicit generic mapping on a real serializer: no built-in semantic profile is used.
        var generic=CompatDefinitions.machine(mi.data.get("type").getAsString());generic.source="confirmed";generic.modVersion=CompatibilityRecipes.modVersion(generic.type);generic.shape=CompatJson.shape(mi.data);CompatibilityRecipes.confirm(generic,mi.data);check(RecipeAdapters.get(generic.type) instanceof CompatibilityAdapter,"Confirmed mapping installs shared adapter");CompatibilityRecipes.register(CompatDefinitions.machine(generic.type),mi.data);
        EditorRuntime.saveDraft();var issues=EditorRuntime.validationIssues();report.add("validationIssues",ProjectStore.JSON.toJsonTree(issues));check(issues.isEmpty(),"All native drafts validate: "+issues);var review=EditorRuntime.review();EditorRuntime.apply(review);result=null;EditorRuntime.reloadResult(false,rst->result=rst);
    }
    @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!Boolean.getBoolean("kubejs.editor.verifyUniversal")||phase==99)return;var mc=Minecraft.getInstance();ticks++;try{
        if(ticks>7200)throw new AssertionError("Timeout phase "+phase);
        if(phase==0&&mc.screen instanceof TitleScreen&&ticks>80){stage=Files.exists(root().resolve("universal-stage1.json"))?2:1;phase=1;ticks=0;mc.tell(()->mc.createWorldOpenFlows().openWorld("EditorVerification",()->{}));return;}
        if(phase==1&&mc.level!=null&&mc.player!=null&&WorkspaceJeiPlugin.runtime!=null&&ticks>160){EditorRuntime.project();if(stage==2){for(String mode:List.of("create_item","transmute_input","upgrade_tier")){var variant=nativeData("compat:ritual");variant.addProperty("type","forbidden_arcanus:ritual");CompatDefinitions.switchRitualResult(variant,"forbidden_arcanus:"+mode);var layout=CompatJeiLayouts.create("compat:ritual",variant);check(layout.layout()!=null,"Native typed-result JEI layout rebuild "+mode+": "+layout.error());if(mode.equals("upgrade_tier")){check(layout.layout().getRecipeCategory().getClass().getSimpleName().equals("UpgradeTierCategory"),"Tier upgrade switches JEI category");var regions=CompatJeiLayouts.bind("compat:ritual",layout,new RecipePresentation(variant,CompatDefinitions.ritual(variant)));check(regions.containsKey("/forge_tier@0")&&regions.containsKey("/result/result_tier@0")&&regions.containsKey("/essences/blood@0"),"Upgrade layout binds both levels and special resources");}}var ritualView=adapter("compat:ritual").presentation(nativeData("compat:ritual"));var catalyst=ritualView.bindings().stream().filter(b->b.field().role==CompatDefinition.Role.CATALYST).findFirst().orElseThrow();var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(ResourceLocation.parse("forbidden_arcanus:divine_pact"));check(CompatibilityScreen.canonical(new net.minecraft.world.item.ItemStack(item),catalyst).get("item").getAsString().equals("forbidden_arcanus:divine_pact"),"Enhancer drag resolves native registry holder");boolean rejected=false;try{CompatibilityScreen.canonical(new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.STONE),catalyst);}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Ordinary items cannot be used as enhancer definitions");check(!SimpleRecipes.enabled(),"Discovery disabled across real restart");EditorRuntime.recipes();check(EditorRuntime.state().applied.recipes.size()==3,"All three rules survive restart");check(nativeData("compat:mi_eight_four").get("eu").getAsInt()==32,"MI native energy persists");check(nativeData("compat:apparatus_6").get("sourceCost").getAsInt()==123,"Ars native source persists");check(nativeData("compat:ritual").get("forge_tier").getAsInt()==2,"Ritual native tier persists");result=null;EditorRuntime.revokeRecipe("compat:mi_eight_four",r->result=r);phase=20;ticks=0;return;}
            SimpleRecipes.setEnabled(EditorRuntime.root(),true);EditorRuntime.invalidateRecipes();EditorRuntime.recipes();var schemas=new JsonArray();if(ScriptIndex.schemas()!=null)for(var s:ScriptIndex.schemas().namespaces.values().stream().flatMap(ns->ns.values().stream()).toList())if(s.id.getNamespace().equals("ars_nouveau")||s.id.getNamespace().equals("modern_industrialization")||s.id.getNamespace().equals("enderio")){var o=new JsonObject();o.addProperty("schema",s.id.toString());var keys=new JsonArray();for(var k:s.schema.keys)keys.add(k.name+":"+k.component.type().id()+":"+k.role);o.add("keys",keys);schemas.add(o);}report.addProperty("schemaStorageAvailable",ScriptIndex.schemas()!=null);if(ScriptIndex.schemas()!=null)report.add("schemaStorageNamespaces",ProjectStore.JSON.toJsonTree(ScriptIndex.schemas().namespaces.keySet()));report.add("schemas",schemas);saveReport();var automatic=EditorRuntime.recipes().stream().filter(r->RecipeAdapters.get(r.type()) instanceof CompatibilityAdapter a&&a.definition.source.equals("kubejs-schema")).toList();check(!automatic.isEmpty(),"Public KubeJS schema discovers other recipe types");report.addProperty("schemaMappedRecipes",automatic.size());layouts();manualMapping();prepare();phase=2;ticks=0;return;}
        if(phase==2&&result!=null){check(result.success(),"Apply native transaction "+result.message());check(EditorRuntime.state().activation==null,"Activation promotes only after verification");check(nativeData("compat:mi_eight_four").get("eu").getAsInt()==32,"MI energy actually loaded");check(nativeData("compat:ritual").get("forge_tier").getAsInt()==2,"Ritual tier actually loaded");check(nativeData("compat:apparatus_6").get("sourceCost").getAsInt()==123,"Ars source actually loaded");nativeChecks=mc.getSingleplayerServer().submit(()->{try{return NativeProcessingChecks.run(mc.getSingleplayerServer());}catch(Exception e){throw new RuntimeException(e);}});phase=5;ticks=0;return;}
        if(phase==5&&nativeChecks.isDone()){report.add("nativeProcessing",nativeChecks.join());checks+=2;shots.addAll(List.of("compat:mi_eight_four","compat:ritual","compat:apparatus_1","compat:apparatus_2","compat:apparatus_4","compat:apparatus_6","compat:apparatus_8"));show(shots.getFirst(),2);phase=3;ticks=0;return;}
        if(phase==3&&ticks>20){String id=shots.get(shotIndex);check(WorkspaceJeiPlugin.runtime.getIngredientListOverlay().isListDisplayed(),"JEI ingredients visible on shared editor");Screenshot.grab(mc.gameDirectory,"universal-"+id.substring(id.indexOf(':')+1)+"-scale2.png",mc.getMainRenderTarget(),c->{});shotIndex++;if(shotIndex<shots.size()){show(shots.get(shotIndex),2);ticks=0;return;}show("compat:ritual",3);phase=4;ticks=0;return;}
        if(phase==4&&ticks>20){Screenshot.grab(mc.gameDirectory,"universal-ritual-scale3.png",mc.getMainRenderTarget(),c->{});SimpleRecipes.setEnabled(EditorRuntime.root(),false);finish();return;}
        if(phase==20&&result!=null){check(result.success(),"Individual revoke succeeds");check(nativeData("compat:mi_eight_four").get("eu").getAsInt()==25,"Revocation restores native source");check(EditorRuntime.state().applied.recipes.size()==2,"Unrelated rules remain applied");EditorRuntime.rollback();result=null;EditorRuntime.reloadResult(false,r->result=r);phase=21;ticks=0;return;}
        if(phase==21&&result!=null){check(result.success(),"Rollback reload succeeds");check(nativeData("compat:mi_eight_four").get("eu").getAsInt()==32,"Rollback restores prior native modification");finish();}
    }catch(Throwable e){report.addProperty("passed",false);var trace=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(trace));report.addProperty("error",trace.toString());try{saveReport();}catch(Exception ignored){}e.printStackTrace();phase=99;mc.stop();}}
}
